extension WindowsLayouts {
    /// Where a character sits on a Windows layout.
    struct Key {
        let scancode: UInt8
        let shift: Bool
        let altGr: Bool
    }

    private static var cache: [UInt32: [Character: Key]] = [:]

    /// The key that types `ch` on the layout `klid`, nil when the layout has none for it.
    static func key(for ch: Character, klid: UInt32) -> Key? {
        if cache[klid] == nil {
            guard let packed = packed[klid] else { return nil }
            var table: [Character: Key] = [:]
            let scalars = Array(packed.unicodeScalars)
            var i = 0
            while i + 3 < scalars.count {
                let hex = String(String.UnicodeScalarView(scalars[(i + 1)...(i + 2)]))
                if let code = UInt8(hex, radix: 16), let lv = Int(String(scalars[i + 3])) {
                    table[Character(scalars[i])] = Key(scancode: code, shift: lv == 1 || lv == 3, altGr: lv >= 2)
                }
                i += 4
            }
            cache[klid] = table
        }
        return cache[klid]?[ch]
    }
}
